  tool_yaml_json_how_title: 'Cara pakai',
  tool_yaml_json_indent_2: '2 spasi',
  tool_yaml_json_indent_4: '4 spasi',
  tool_yaml_json_indent_label: 'Indentasi',
  tool_yaml_json_indent_minify: 'Minifikasi JSON',
